#include "game_engine.hpp"
#include "game_feedback.hpp"
namespace remora {
void GameEngine::memory(){int d=s.difficulty;if(hard())s.sequence=pattern(std::min(30,(int[]){0,0,4,6,8}[d]+(s.level-1)/2),s.sequence);else s.sequence.push_back(key());s.phase=Phase::Ready;s.mirror=s.mode==1&&d>=3;later(650,[this,d]{s.phase=Phase::Watch;int interval=std::max(130,int(std::lround((int[]){1050,850,400,280,190}[d]*pace())));for(size_t i=0;i<s.sequence.size();i++){int n=s.sequence[i];later(250+i*interval,[this,n]{s.pulse=n;if(sound)sound("tone");});later(250+i*interval+std::lround(interval*.6),[this]{s.pulse=0;});}later(300+s.sequence.size()*interval,[this,d]{s.phase=Phase::Input;s.pulse=0;deadline(hard()?std::max(300,int(std::lround((int[]){0,0,1000,700,480}[d]*pace()))):0);});});}
void GameEngine::memoryPress(int n){int expected=s.sequence[s.mode==1?s.sequence.size()-1-s.input:s.input];if(s.mirror)expected=7-expected;if(n!=expected){fail("URUTAN TIDAK TEPAT");return;}s.input++;points(10);if(sound)sound("correct");if(s.input==int(s.sequence.size()))clear();else deadline(hard()?std::max(300,int(std::lround((int[]){0,0,1000,700,480}[s.difficulty]*pace()))):0);}
void GameEngine::reaction(){s.hits=0;s.required=std::min(15,(int[]){1,1,3,5,7}[s.difficulty]+burden());s.fakeUsed=false;reactionCue();}
void GameEngine::reactionCue(){cancel();s.phase=Phase::ReactionWait;s.target=key();s.pulse=0;later(700+rnd(1400),[this]{if(hard()&&!s.fakeUsed&&random()<.6){s.fakeUsed=true;s.phase=Phase::ReactionFake;later(320,[this]{reactionCue();});return;}s.fakeUsed=false;s.phase=Phase::ReactionGo;s.reactionStart=s.now;s.pulse=s.target;if(sound)sound("go");deadline(std::max(200,int(std::lround((int[]){3000,2200,700,450,320}[s.difficulty]*pace()))));});}
void GameEngine::reactionPress(int n){if(s.phase!=Phase::ReactionGo){fail(s.phase==Phase::ReactionFake?"TERTIPU GO MERAH":"TERLALU AWAL");return;}int expected=s.difficulty==4?neighbor(s.target,1):s.difficulty==3?7-s.target:s.target;if(n!=expected){fail("TARGET TIDAK TEPAT");return;}int elapsed=s.now-s.reactionStart;cancel();s.times.push_back(elapsed);s.hits++;points(50);if(sound)sound("correct");if(s.hits>=s.required){s.clears++;int sum=0;for(int t:s.times)sum+=t;s.elapsed=int(std::lround(double(sum)/s.times.size()));s.phase=Phase::ReactionResult;s.message=WinPhrases[s.mode][winCounts[s.mode]++%15];if(record)record(2,s.elapsed,true);later(1450,[this]{nextLevel();});}else{s.phase=Phase::Clear;later(950,[this]{reactionCue();});}}
}
